INSERT INTO "components" VALUES('pic16f887','microcontroladores','PIC16F887-I/P','PIC','chip',1,1,'{"accelerators": "Nenhum dedicado", "adc": "10 bits · 14 canais", "clock": 20, "cpu": "PIC · 8 bits", "dac": "Não", "datasheet": "pic16f887.pdf", "eeprom": "256 B", "external": "Não", "flash": "8.192 palavras × 14 bits (14 KiB)", "flash_short": "14 KiB", "gpio": "35 (RE3 somente entrada)", "logic": "Conforme VDD (2–5,5 V)", "mips_peak": 5, "notes": "RE3/MCLR é somente entrada. Clock máximo depende da tensão. Pinos analógicos precisam de configuração para uso digital.", "origin": "Inventario_Componentes_Eletronicos_Obsidian.md · 07/05/2026", "oscillator": "Interno até 8 MHz; externo até 20 MHz", "package": "PDIP-40", "pin_guide": "pic", "pinout": "pic16f887.png", "pinout_credit": "Microchip Technology · diagrama PDIP-40 e Tabela 3 do datasheet 41291D", "pinout_source": "pic16f887.pdf", "processing_class": "Essencial", "programmer": "PICkit 3 · ICSP", "pwm": "ECCP + CCP", "ram": 368, "serial": "EUSART · SPI · I2C (MSSP compartilhado)", "subtitle": "PDIP-40", "temperature": "−40 a +85 °C (sufixo I)", "timers": "2 × 8 bits + 1 × 16 bits", "use": "Controle geral, muitos sensores, teclado e display paralelo.", "voltage": "2–5,5 V"}');
