INSERT INTO "components" VALUES('uno','microcontroladores','Arduino Uno','AVR','placa',0,5,'{"accelerators": "Nenhum dedicado", "adc": "10 bits · 6 entradas", "clock": 16, "cpu": "AVR · 8 bits", "dac": "Não", "datasheet": "atmega328p.pdf", "eeprom": "1 KiB", "external": "Não", "flash": "32 KiB (bootloader ocupa parte)", "flash_short": "32 KiB", "gpio": "20 sinais digitais (inclui A0–A5)", "logic": "5 V", "mips_peak": 16, "notes": "Referência Uno R3 com ATmega328P; revisão física não registrada.", "origin": "Relato do usuário · 12/09/2026", "oscillator": "16 MHz na placa", "package": "Placa · ATmega328P", "pin_guide": "avr", "pinout": "uno-pinout-simple.png", "pinout_credit": "Simples: desenho do almoxarifado a partir do datasheet ATmega328P (Figura 1-1, tabela 28.1) e da folha oficial Arduino A000066 · oficial: Arduino, CC BY-SA 4.0", "pinout_source": "uno-pinout.pdf", "pinouts": [{"file": "uno-pinout-simple.png", "notice": "", "title": "Simples · todos os pinos com porta, número no chip e funções"}, {"file": "uno-pinout.png", "notice": "", "title": "Folha oficial Arduino UNO R3 (A000066) · referência"}], "processing_class": "Básico", "programmer": "USB com bootloader · ICSP AVR (não PICkit)", "pwm": "6 saídas · 8 bits", "ram": 2048, "serial": "UART · SPI · I2C", "subtitle": "Placa · ATmega328P", "temperature": "Consultar limites da placa e do chip", "timers": "2 × 8 bits + 1 × 16 bits", "use": "Prototipagem rápida, módulos de 5 V e bibliotecas Arduino.", "voltage": "5 V"}');
