INSERT INTO "components" VALUES('bluepill','microcontroladores','BluePill','STM32','placa',0,7,'{"accelerators": "Nenhum dedicado", "adc": "12 bits · 10 canais externos", "clock": 72, "coremark": 108.26, "coremark_note": "Referência publicada para o STM32F103RB da mesma família; não é uma medição do STM32F103C8 exato.", "coremark_per_mhz": 1.5036, "cpu": "Cortex-M3 · 32 bits", "dac": "Não", "datasheet": "stm32f103c8.pdf", "dmips": 90, "dmips_per_mhz": 1.25, "eeprom": "Sem EEPROM", "external": "Não registrada", "flash": "64 KiB", "flash_short": "64 KiB", "gpio": "Até 37 no chip; depende da placa", "logic": "3,3 V", "notes": "STM32F103C8T6 confirmado pelo usuário; duas unidades USB-C e uma micro-USB. Não assumir 128 KiB de Flash: o datasheet C8 declara 64 KiB. USB e CAN compartilham recursos nesta família. Não confundir com o módulo ADS1256 + STM32F103.", "origin": "Usuário: três BluePill; associação ao TCC. Marcação STM32F103C8T6 confirmada pelo usuário em 12/09/2026.", "oscillator": "8 MHz externo típico; HSI interno 8 MHz", "package": "STM32F103C8T6 · LQFP-48", "pin_guide": "stm32", "pinout": "bluepill-pinout.png", "pinout_credit": "Diagrama genérico STM32F103 · Rasmus Friis Kjeldsen (reblag.dk/stm32) · CC BY-SA 4.0", "pinout_notice": "Diagrama genérico da placa BluePill STM32F103. As três unidades são STM32F103C8T6, duas com conector USB-C e uma com micro-USB; o desenho mostra a variante micro-USB. Confira a posição do conector e dos jumpers BOOT antes de ligar.", "pinout_source": "stm32f103c8.pdf", "processing_class": "Intermediário", "programmer": "ST-Link V2 · SWD; bootloader UART via CH343P", "pwm": "Timers com PWM", "ram": 20480, "relative_bluepill": 1.0, "serial": "USART · SPI · I2C · USB FS · CAN 2.0B", "subtitle": "STM32F103C8T6", "temperature": "−40 a +85 °C", "timers": "3 gerais + 1 avançado · 16 bits", "use": "Controle de sensores, comunicação e temporização com mais memória que os PICs.", "variant": "Três unidades STM32F103C8T6: duas com conector USB-C e uma com micro-USB.", "voltage": "3,3 V"}');
INSERT INTO "components" VALUES('blackpill','microcontroladores','WeAct BlackPill','STM32','placa',0,8,'{"accelerators": "FPU · DSP", "adc": "12 bits · até 10 canais externos", "clock": 100, "coremark": 339, "coremark_per_mhz": 3.39, "cpu": "Cortex-M4F · 32 bits · FPU", "dac": "Não", "datasheet": "stm32f411ce.pdf", "dmips": 125, "dmips_per_mhz": 1.25, "eeprom": "Sem EEPROM", "evidence": "docs/evidence/blackpill-variant.png", "external": "8 MiB (8 MB anunciados) · Flash SPI WeAct montada", "flash": "512 KiB", "flash_short": "512 KiB", "gpio": "Até 36 no chip; pinos ocupados na montagem", "logic": "3,3 V", "notes": "No TCC: SPI1 PA4–PA7 para Flash externa; SPI2 PB13–PB15 para ADS1256. O diagrama WeAct v2.0+ é referência, não o mapa de fios da montagem. Não possui DAC nem CAN.", "origin": "TCC/DOCUMENTACAO_TECNICA_CRONOLOGICA.md e notas BlackPill do Obsidian; Flash externa de 8 MB confirmada pelo usuário em 12/09/2026", "oscillator": "Cristal 25 MHz; núcleo até 100 MHz (96 MHz no TCC)", "package": "STM32F411CEU6 · UFQFPN-48", "pin_guide": "stm32", "pinout": "blackpill-pinout.png", "pinout_credit": "WeAct Studio · desenho de Richard Balint", "pinout_source": "blackpill-pinout.pdf", "processing_class": "Avançado", "programmer": "ST-Link V2 · SWD; USB DFU; bootloader WeAct usado no TCC", "pwm": "Timers com PWM", "ram": 131072, "relative_bluepill": 1.39, "serial": "USART · SPI/I2S · I2C · USB FS · SDIO", "subtitle": "STM32F411CEU6", "temperature": "−40 a +85 °C (chip)", "timers": "Até 11 na família, incluindo watchdogs e SysTick", "use": "Aquisição e processamento de sinais; já usada com ADS1256 e display no TCC.", "variant": "F411 25M HSE 8MFlash", "voltage": "3,3 V"}');
INSERT INTO "components" VALUES('g474','microcontroladores','WeAct G474 Long','STM32','placa',0,9,'{"accelerators": "FPU · DSP · CORDIC · FMAC", "adc": "5 ADCs · 12 bits (canais dependem dos pinos)", "clock": 170, "coremark": 569, "coremark_per_mhz": 3.35, "cpu": "Cortex-M4F · 32 bits · FPU · DSP", "dac": "7 canais no chip; nem todos externos", "datasheet": "stm32g474.pdf", "dmips": 213, "dmips_per_mhz": 1.25, "eeprom": "Sem EEPROM", "external": "Não registrada", "flash": "512 KiB", "flash_short": "512 KiB", "gpio": "Até 40 no chip; sinais multiplexados", "logic": "3,3 V", "notes": "128 KiB SRAM = 96 KiB + 32 KiB CCM. Long muda o formato, não a capacidade do chip. Recursos máximos da família não equivalem a canais expostos no encapsulamento de 48 pinos.", "origin": "Relato do usuário + conversa “Comparar placas STM32” · CEU6 Long confirmada", "oscillator": "HSI interno 16 MHz + PLL; cristal conforme esquema", "package": "STM32G474CEU6 · UFQFPN-48", "pin_guide": "stm32", "pinout": "g474-long-pinout-simple.png", "pinout_credit": "Desenhos do almoxarifado · simples: colunas sobre o render oficial WeAct · completa: ST DS12288 Rev 6 (tabelas 12 e 13), esquema WeAct e foto da placa do usuário · pinos numerados pelo UFQFPN48", "pinout_source": "g474-long-pinout.pdf", "pinouts": [{"file": "g474-long-pinout-simple.png", "notice": "", "title": "Simples · GPIO e funções principais"}, {"file": "g474-long-pinout-full.png", "notice": "", "title": "Completa · todas as funções (AF0–AF15 com número + funções adicionais)"}], "processing_class": "Avançado especializado", "programmer": "ST-Link V2 · SWD; USB DFU ou UART conforme bootloader", "pwm": "HRTIM + timers convencionais", "ram": 131072, "relative_bluepill": 2.37, "schematic": "g474-long-schematic.pdf", "serial": "USART/UART · SPI/I2S · I2C · USB FS · FDCAN", "special": "CORDIC · FMAC · comparadores · OPAMP · HRTIM", "subtitle": "STM32G474CEU6", "temperature": "−40 a +85 °C (sufixo 6)", "timers": "HRTIM de alta resolução + timer